<!--
 * 字典类型管理页面 — 字典类型的分页列表、搜索、新增、编辑、删除
 *
 * @path apps\system-web\src\views\dict-type\index.vue
 * @author ydsz-team
 * @since 1.1.0
-->
<script lang="ts" setup>
/**
 * 字典类型（列表页）
 * <p>消费后端契约 DictController（src/api/dict.ts，auto-generated by bash/gen-contract.py）的字典类型列表页：
 * 分页查询 page、编辑/删除（remove）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/dict';
import type { DictPageQuery, DictTypeVO, PageQuery } from '#/api/models';

import DictTypeForm from './dict-type-form.vue';

defineOptions({ name: 'DictTypeManagement' });

const { t } = useI18n();

/** 请求控制器，用于取消未完成的请求 */
const abortController = new AbortController();

/** 行类型：真实契约 DictTypeVO（字段以 models.ts 为准） */
type DictTypeRow = DictTypeVO;

/** 分页查询参数：契约 DictPageQuery + 通用分页字段（models.ts PageQuery） */
type DictTypePageQueryParams = DictPageQuery & PageQuery;

/** 状态是否启用（后端 status 为字符串，兼容 '1' / 'ENABLED' 两种取值） */
function isEnabled(status?: string): boolean {
  return status === '1' || status === 'ENABLED';
}

const gridOptions: VxeTableGridOptions<DictTypeRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'typeCode', title: t('typeCode'), width: 150 },
    { field: 'typeName', title: t('typeName'), width: 150 },
    { field: 'description', title: t('description'), width: 220 },
    {
      field: 'status',
      title: t('status'),
      width: 80,
      slots: {
        default: ({ row }) => {
          const dictType = row as DictTypeRow;
          return h(
            ElTag,
            { type: isEnabled(dictType.status) ? 'success' : 'info' },
            () => (isEnabled(dictType.status) ? '启用' : '禁用'),
          );
        },
      },
    },
    {
      field: 'action',
      title: t('action'),
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const dictType = row as DictTypeRow;
          return h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(dictType) }, () => t('edit')),
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(dictType) }, () => t('delete')),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const query: DictTypePageQueryParams = {
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        };
        const res = await page({ query });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'typeName', title: t('typeName'), itemRender: { name: 'Input', props: { placeholder: t('typeName') } } },
      { field: 'typeCode', title: t('typeCode'), itemRender: { name: 'Input', props: { placeholder: t('typeCode') } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [DictTypeFormModal, dictTypeFormApi] = useYDSZModal({ connectedComponent: DictTypeForm });

function handleAdd() {
  dictTypeFormApi.open();
}

function handleEdit(row: DictTypeRow) {
  dictTypeFormApi.setData({ record: row });
  dictTypeFormApi.open();
}

async function handleDelete(row: DictTypeRow) {
  try {
    await ElMessageBox.confirm(`确定删除「${row.typeName ?? row.typeCode ?? ''}」吗？`, '删除确认', { type: 'warning' });
    if (row.id) await remove({ id: row.id });
    ElMessage.success(t('operationSuccess'));
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 页面卸载时取消未完成的请求 */
onUnmounted(() => {
  abortController.abort();
});
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="字典类型">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">{{ t('create') }}</ElButton>
      </template>
    </Grid>
    <DictTypeFormModal @success="gridApi.query()" />
  </Page>
</template>